               {"script": "mobile: tap", "args": [{"x": x, "y": y}]})

def window_size():
    return req("GET", f"/session/{SID}/window/size")["value"]

def send_keys(el, text):
    return req("POST", f"/session/{SID}/element/{elid(el)}/value", {"text": text})

cmd = sys.argv[1] if len(sys.argv) > 1 else "session"
