    session()
elif cmd == "size":
    session()
    print(window_size())

import json, time, sys, urllib.request

BASE = "http://127.0.0.1:4723"
SID = sys.argv[1]

def req(method, path, body=None, timeout=120):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(BASE + path, data=data, method=method,
                               headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(r, timeout=timeout) as resp:
        return json.loads(resp.read().decode())

def find(using, value, timeout=8):
    end = time.time() + timeout
    while time.time() < end:
        try:
            els = req("POST", f"/session/{SID}/elements", {"using": using, "value": value})["value"]
            if els:
                return els[0]
        except Exception:
            pass
        time.sleep(0.5)
    return None

def elid(el):
    return el.get("ELEMENT") or el.get("element-6066-11e4-a52e-4f735466cecf")

def click(el):
    return req("POST", f"/session/{SID}/element/{elid(el)}/click")

def label(el):
    try:
        return req("GET", f"/session/{SID}/element/{elid(el)}/attribute/label")["value"]
    except Exception:
        return None

def tap(x, y):
    return req("POST", f"/session/{SID}/execute/sync",
               {"script": "mobile: tap", "args": [{"x": x, "y": y}]})

size = req("GET", f"/session/{SID}/window/size")["value"]
W, H = size["width"], size["height"]
print("WINDOW", W, H, flush=True)

tab = None
for aid in ["Search", "Search and Explore", "search"]:
    tab = find("accessibility id", aid, timeout=2)
    if tab:
        print("TAB via", aid, label(tab), flush=True)
        break
if tab:
    click(tab)
else:
    print("TAB via coords", flush=True)
    tap(int(W * 0.302), int(H * 0.937))
time.sleep(2)

field = find("class name", "XCUIElementTypeTextField", timeout=8) or \
        find("class name", "XCUIElementTypeSearchField", timeout=3)
if not field:
    print("no field; tapping input area", flush=True)
    tap(int(W * 0.45), int(H * 0.087))
    time.sleep(1)
    field = find("class name", "XCUIElementTypeTextField", timeout=5)
print("FIELD", field, flush=True)
click(field)
time.sleep(0.5)
req("POST", f"/session/{SID}/element/{elid(field)}/value", {"text": "whiskers.test"})
print("typed", flush=True)
time.sleep(4)

chain = '**/XCUIElementTypeAny[`label CONTAINS "whiskers"`]'
els = req("POST", f"/session/{SID}/elements", {"using": "class chain", "value": chain})["value"]
info = []
for e in els[:12]:
    info.append(label(e))
print("MATCHES", info, flush=True)
target = None
for e in els:
    lb = label(e) or ""
    if "whiskers" in lb.lower() and "TextField" not in lb and lb != "whiskers.test":
        target = e
        break
if target is None and els:
    target = els[-1]
if target:
    print("CLICKING", label(target), flush=True)
    click(target)
else:
    print("NO TARGET FOUND", flush=True)
time.sleep(3)
print("DONE", flush=True)

